def algorithm(func, dim, lb, ub, budget, rng):
    def fitness(x):
        return func(x)

    pop_size = 100
    x = np.random.uniform(lb, ub, (pop_size, dim))
    best_x = None
    best_f = np.inf

    for i in range(budget):
        f = np.array([fitness(xi) for xi in x])
        idx = np.argsort(f)
        x_sorted = x[idx]
        f_sorted = f[idx]

        mu = 0.1 * pop_size
        sigma = (ub - lb) / 2
        best_x = x_sorted[0]
        best_f = f_sorted[0]

        if rng.random() < 0.1:
            mu *= rng.random()
        for j in range(pop_size):
            if j < mu:
                continue

            p1_idx = rng.randint(0, pop_size)
            p2_idx = rng.randint(0, pop_size)

            c = x_sorted[p1_idx] + rng.uniform(-1, 1) * (x_sorted[p1_idx] - x_sorted[p2_idx])
            cx = (c[0] + x_sorted[p2_idx][0]) / 2
            x[j] = np.clip(c[:dim], lb, ub)

        for j in range(pop_size):
            if rng.random() < 0.01:
                x[j] += rng.uniform(-sigma, sigma) * (ub - lb)

    return best_x
